const C8 = "8. Deductions from Gross Total Income";
const C9 = "9. Assessment of Various Entities";
const C10 = "10. Assessment of Trusts and Institutions, Political Parties and Other Special Entities";
const C11 = "11. Tax Planning, Tax Avoidance and Tax Evasion";
const C12 = "12. Taxation of Digital Transactions";
const C13 = "13. Deduction, Collection and Recovery of Tax";
const C14 = "14. Income Tax Authorities";
